        _log.Add("open:" + name);
    }

    public async ValueTask DisposeAsync()
    {
        if (_disposed) return;

        _disposed = true;
        await Task.Yield();
        _log.Add("flush:" + _name);
        _log.Add("dispose:" + _name);
    }

    // The synchronous path cannot await, so it cannot flush.
    void IDisposable.Dispose()
    {
        if (_disposed) return;

